Let $n\in\mbox{${\mathbb N}$}, n\geq 2$ and let $A_1, A_2, \ldots, A_n$ be selfadjoint operators in $\mathcal{H}$ with scalar-valued spectral measures $\lambda_{A_1}, \ldots, \lambda_{A_n}$. We let
\begin{equation*}
\Gamma^{A_1,A_2, \ldots, A_n} : L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}) \rightarrow \mathcal{B}_{n-1}(\mathcal{S}^2(\mathcal{H}))
\end{equation*}
to be the unique linear map such that for any $f_i \in L^{\infty}(\lambda_{A_i}), i=1, \ldots, n$ and for any $X_1, \ldots, X_{n-1} \in \mathcal{S}^2(\mathcal{H})$,
\begin{align} \left[\Gamma^{A_1,A_2, \ldots, A_n}(f_1\otimes\cdots\otimes f_n)\right]
& (X_1,\ldots, X_{n-1})\\ \nonumber
& =f_1(A_1)X_1f_2(A_2) \cdots f_{n-1}(A_{n-1})X_{n-1}f_n(A_n).
\end{align}

Let $\alpha_1, \ldots, \alpha_{n-1}, \alpha \in (1, \infty)$, let $n \geq 1$, $A_1, \ldots, A_n$ be selfadjoint operators in $\mathcal{H}$ and $(\varphi_k)_{k\geq 1}, \varphi \in L^{\infty}(\lambda_{A_1} \times \cdots \lambda_{A_n})$. Assume that $(\varphi_k)_k$ is $w^*$-convergent to $\varphi$ and that $\left(\Gamma^{A_1, \ldots, A_n}(\varphi_k) \right)_{k\geq 1} \subset \mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})$ is bounded. Then $\Gamma^{A_1, \ldots, A_n}(\varphi) \in \mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})$ with
\begin{align*}
& \| \Gamma^{A_1, \ldots, A_n}(\varphi)\|_{\mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})} \\
& \ \ \ \ \leq \liminf_k \| \Gamma^{A_1, \ldots, A_n}(\varphi_k)\|_{\mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})}
\end{align*}
and for any $X_i \in \mathcal{S}^{\alpha_i}(\mathcal{H}), 1 \leq i \leq n-1$,
$$
\left[ \Gamma^{A_1, \ldots, A_n}(\varphi_k) \right](X_1, \ldots, X_{n-1}) \underset{k \to \infty}{\longrightarrow} \left[ \Gamma^{A_1, \ldots, A_n}(\varphi) \right](X_1, \ldots, X_{n-1})
$$
weakly in $\mathcal{S}^{\alpha}(\mathcal{H})$.

Since $\left(\Gamma^{A_1, \ldots, A_n}(\varphi_k) \right)_{k\geq 1} \subset \mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})$ is bounded, we can set $C' := \sup_j \|\Gamma^{A_1, \ldots, A_n}(\varphi_j)\|_{\mathcal{B}_{n-1}(\mathcal{S}^{\alpha_1} \times \cdots \times \mathcal{S}^{\alpha_{n-1}}, \mathcal{S}^{\alpha})}$. By Remark $\ref{Ineqmulti}$, there exists a constant $C > 0$ depending only on $n, C', \|X_1\|_{\alpha_1}, \ldots, \|X_{n-1}\|_{\alpha_{n-1}}$ such that, for any $k\geq 1$,
\begin{equation} \| \Gamma_{k,X} - \tilde{\Gamma}_{k,X} \|_p \leq C \epsilon \ \ \text{and} \ \ \| \Gamma_{X} - \tilde{\Gamma}_{X} \|_p \leq C \epsilon.
\end{equation}

By the first part of the proof, there exists $k_0 \in \mathbb{N}$ such that for any $k\geq k_0$,
\begin{equation} | {\mathrm{Tr}\,}((\tilde{\Gamma}_X - \tilde{\Gamma}_{k,X})Y)| < \epsilon.
\end{equation}

\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ \ \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}

Assume that $p=2$. We first prove the result when $\phi_1 = f_1 \otimes \cdots \otimes f_n$ and $\phi_2 = g_j \otimes g_{j+1}$ where for any $1\leq i \leq n, f_i\in L^{\infty}(\lambda_{A_i}), g_j \in L^{\infty}(\lambda_{A_j}), g_{j+1} \in L^{\infty}(\lambda_{A_{j+1}})$. In this case,
$$
\phi_1 \widetilde{\phi_2} = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_j g_j \otimes f_{j+1} g_{j+1} \otimes f_{j+2} \otimes \cdots \otimes f_n
$$
so we have, by \eqref{MOItensor},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) g_j(A_j) K_j g_{j+1}(A_{j+1}) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(g_j\otimes g_{j+1})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right),
\end{align*}
which proves the result for such $\phi_1$ and $\phi_2$. Note that this formula is bilinear in $(\phi_1, \phi_2)$, hence the result holds true whenever $\phi_1 \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $\phi_2 \in L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$.

In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Fix $s\in S$ and assume first that $\phi_{1,s} = f_1 \otimes \cdots \otimes f_n$. By the previous computation, we have, for any $t\in T$,
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_{2,t}})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_{2,t})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n).
\end{split}
\end{align}
where $\widetilde{\phi_{2,t}}$ is defined as in \eqref{fortilde}. By the $w^*$-continuity of $\Gamma^{A_j, A_{j+1}}$, we get that the right-hand side of \eqref{for1} converges, in the $w^*$-topology of $\mathcal{S}^2(\mathcal{H})$, to
\begin{align*}
& f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
For the left-hand side of \eqref{for1}, we show that $(\phi_{1,s} \widetilde{\phi_{2,t}})_{t\in T}$ $w^*$-converges to $\phi_{1,s} \widetilde{\phi_2}$. Indeed, let $g\in L^1(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Then, writing $\Omega = \sigma(A_1) \times \cdots \times \sigma(A_n)$, we have, by Fubini's theorem,
\begin{align*}
& \int_{\Omega} \phi_{1,s} \widetilde{\phi_{2,t}} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& = \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \left( \int_{\prod_{i \neq j,j+1} \sigma(A_i)} \phi_{1,s} g \ \prod_{i \neq j,j+1}\text{d}\lambda_{A_j} \right) \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \\
& := \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}.
\end{align*}
By Fubini's theorem, we have the inequality
\begin{align*}
\int_{\sigma(A_j) \times \sigma(A_{j+1})} | \psi_s | \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}
& \leq \int_{\Omega} | \phi_{1,s} g | \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& \leq \| \phi_{1,s} \|_{\infty} \| g\|_{1},
\end{align*}
which shows that $\psi_s \in L^1(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Hence,
$$
\int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \underset{t}{\longrightarrow} \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_2 \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}},
$$
which is in turn equal to $\displaystyle \int_{\Omega} \phi_{1,s} \widetilde{\phi_2} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n}$. This shows that $(\phi_{1,s} \widetilde{\phi_{2,t}})_{t\in T}$ $w^*$-converges to $\phi_{1,s} \widetilde{\phi_2}$. By $w^*$-continuity of multiple operator integrals, we have, taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for1},
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}
\end{align}
Note that, by linearity, this equality holds true whenever $\phi_{1,s} \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}).$ Since $(\phi_{1,s} \widetilde{\phi_2})_{s\in S}$ $w^*$-converges to $\phi_1 \widetilde{\phi_2}$ we have, by taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for2},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Assume now that $1\leq p < \infty$ and let $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. By assumption, there exist $A_p, B_p >0$ such that 
\begin{align} \begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p \| \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) \|_p \|K_{j+1}\|_p \ldots \| K_{n-1}\|_p \\
& \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{split}
\end{align}
Since for all $1\leq i \leq n-1, K_i \in \mathcal{S}^2(\mathcal{H})$, equality \eqref{fortildeeq} holds and we deduce the inequality
\begin{align} \left\| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \right\|_p  \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{align}
By density of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$ in $\mathcal{S}^p(\mathcal{H})$, we get that $\Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2}) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$ and that inequalities \eqref{densitysimp1} and \eqref{densitysimp2} hold true for any $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$.

Finally, to prove equality \eqref{fortildeeq} in the case when $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$, we approximate $K_i, 1\leq i \leq n-1,$ by elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$, using inequalities \eqref{densitysimp1} and \eqref{densitysimp2}.

\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_{2,t}})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_{2,t})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n).
\end{split}

\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}

\begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p \| \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) \|_p \|K_{j+1}\|_p \ldots \| K_{n-1}\|_p \\
& \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{split}

Assume that $p=2$. We first prove the result when $\phi_1 = f_1 \otimes \cdots \otimes f_n$ and $\phi_2 = g_j \otimes g_{j+1}$ where for any $1\leq i \leq n, f_i\in L^{\infty}(\lambda_{A_i}), g_j \in L^{\infty}(\lambda_{A_j}), g_{j+1} \in L^{\infty}(\lambda_{A_{j+1}})$. In this case,
$$
\phi_1 \widetilde{\phi_2} = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_j g_j \otimes f_{j+1} g_{j+1} \otimes f_{j+2} \otimes \cdots \otimes f_n
$$
so we have, by \eqref{MOItensor},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) g_j(A_j) K_j g_{j+1}(A_{j+1}) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(g_j\otimes g_{j+1})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right),
\end{align*}
which proves the result for such $\phi_1$ and $\phi_2$. Note that this formula is bilinear in $(\phi_1, \phi_2)$, hence the result holds true whenever $\phi_1 \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $\phi_2 \in L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$.

In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Fix $s\in S$ and assume first that $\phi_{1,s} = f_1 \otimes \cdots \otimes f_n$. By the previous computation, we have, for any $t\in T$,
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_{2,t}})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_{2,t})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n).
\end{split}
\end{align}
where $\widetilde{\phi_{2,t}}$ is defined as in \eqref{fortilde}. By the $w^*$-continuity of $\Gamma^{A_j, A_{j+1}}$, we get that the right-hand side of \eqref{for1} converges, in the $w^*$-topology of $\mathcal{S}^2(\mathcal{H})$, to
\begin{align*}
& f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
For the left-hand side of \eqref{for1}, we show that $(\phi_{1,s} \widetilde{\phi_{2,t}})_{t\in T}$ $w^*$-converges to $\phi_{1,s} \widetilde{\phi_2}$. Indeed, let $g\in L^1(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Then, writing $\Omega = \sigma(A_1) \times \cdots \times \sigma(A_n)$, we have, by Fubini's theorem,
\begin{align*}
& \int_{\Omega} \phi_{1,s} \widetilde{\phi_{2,t}} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& = \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \left( \int_{\prod_{i \neq j,j+1} \sigma(A_i)} \phi_{1,s} g \ \prod_{i \neq j,j+1}\text{d}\lambda_{A_j} \right) \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \\
& := \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}.
\end{align*}
By Fubini's theorem, we have the inequality
\begin{align*}
\int_{\sigma(A_j) \times \sigma(A_{j+1})} | \psi_s | \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}
& \leq \int_{\Omega} | \phi_{1,s} g | \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& \leq \| \phi_{1,s} \|_{\infty} \| g\|_{1},
\end{align*}
which shows that $\psi_s \in L^1(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Hence,
$$
\int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \underset{t}{\longrightarrow} \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_2 \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}},
$$
which is in turn equal to $\displaystyle \int_{\Omega} \phi_{1,s} \widetilde{\phi_2} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n}$. This shows that $(\phi_{1,s} \widetilde{\phi_{2,t}})_{t\in T}$ $w^*$-converges to $\phi_{1,s} \widetilde{\phi_2}$. By $w^*$-continuity of multiple operator integrals, we have, taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for1},
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}
\end{align}
Note that, by linearity, this equality holds true whenever $\phi_{1,s} \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}).$ Since $(\phi_{1,s} \widetilde{\phi_2})_{s\in S}$ $w^*$-converges to $\phi_1 \widetilde{\phi_2}$ we have, by taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for2},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes L^{\infty}(\lambda_{A_{j+1}})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \lambda_{A_{j+1}})$. Fix $s\in S$ and assume first that $\phi_{1,s} = f_1 \otimes \cdots \otimes f_n$. By the previous computation, we have, for any $t\in T$,
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_{2,t}})\right] (K_1, \ldots, K_{n-1}) \\
& = f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_{2,t})\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n).
\end{split}
\end{align}
where $\widetilde{\phi_{2,t}}$ is defined as in \eqref{fortilde}.

By the $w^*$-continuity of $\Gamma^{A_j, A_{j+1}}$, we get that the right-hand side of \eqref{for1} converges, in the $w^*$-topology of $\mathcal{S}^2(\mathcal{H})$, to
\begin{align*}
& f_1(A_1)K_1 \ldots K_{j-1} f_j(A_j) \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Indeed, let $g\in L^1(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Then, writing $\Omega = \sigma(A_1) \times \cdots \times \sigma(A_n)$, we have, by Fubini's theorem,
\begin{align*}
& \int_{\Omega} \phi_{1,s} \widetilde{\phi_{2,t}} ~ g \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& = \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \left( \int_{\prod_{i \neq j,j+1} \sigma(A_i)} \phi_{1,s} g \ \prod_{i \neq j,j+1}\text{d}\lambda_{A_j} \right) \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}} \\
& := \int_{\sigma(A_j) \times \sigma(A_{j+1})} \phi_{2,t} \psi_s \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}.
\end{align*}

By Fubini's theorem, we have the inequality
\begin{align*}
\int_{\sigma(A_j) \times \sigma(A_{j+1})} | \psi_s | \ \text{d}\lambda_{A_j}\text{d}\lambda_{A_{j+1}}
& \leq \int_{\Omega} | \phi_{1,s} g | \ \text{d}\lambda_{A_1} \cdots \text{d}\lambda_{A_n} \\
& \leq \| \phi_{1,s} \|_{\infty} \| g\|_{1},
\end{align*}
which shows that $\psi_s \in L^1(\lambda_{A_j} \times \lambda_{A_{j+1}})$.

By $w^*$-continuity of multiple operator integrals, we have, taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for1},
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s})\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{split}
\end{align}

Note that, by linearity, this equality holds true whenever $\phi_{1,s} \in L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n}).$ Since $(\phi_{1,s} \widetilde{\phi_2})_{s\in S}$ $w^*$-converges to $\phi_1 \widetilde{\phi_2}$ we have, by taking the limit in the weak topology of $\mathcal{S}^2(\mathcal{H})$ in \eqref{for2},
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \\
& = \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}

Assume now that $1\leq p < \infty$ and let $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. By assumption, there exist $A_p, B_p >0$ such that 
\begin{align} \begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p \| \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) \|_p \|K_{j+1}\|_p \ldots \| K_{n-1}\|_p \\
& \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{split}
\end{align}
Since for all $1\leq i \leq n-1, K_i \in \mathcal{S}^2(\mathcal{H})$, equality \eqref{fortildeeq} holds and we deduce the inequality
\begin{align} \left\| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \right\|_p  \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{align}
By density of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$ in $\mathcal{S}^p(\mathcal{H})$, we get that $\Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2}) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$ and that inequalities \eqref{densitysimp1} and \eqref{densitysimp2} hold true for any $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$.

Finally, to prove equality \eqref{fortildeeq} in the case when $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$, we approximate $K_i, 1\leq i \leq n-1,$ by elements of $\mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$, using inequalities \eqref{densitysimp1} and \eqref{densitysimp2}.

Assume now that $1\leq p < \infty$ and let $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. By assumption, there exist $A_p, B_p >0$ such that 
\begin{align} \begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1)\right] \left(K_1, \ldots, K_{j-1}, \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j), K_{j+1}, \ldots, K_{n-1}\right) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p \| \left[\Gamma^{A_j, A_{j+1}}(\phi_2)\right](K_j) \|_p \|K_{j+1}\|_p \ldots \| K_{n-1}\|_p \\
& \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{split}
\end{align}

Since for all $1\leq i \leq n-1, K_i \in \mathcal{S}^2(\mathcal{H})$, equality \eqref{fortildeeq} holds and we deduce the inequality
\begin{align} \left\| \left[ \Gamma^{A_1, \ldots, A_n}(\phi_1 \widetilde{\phi_2})\right] (K_1, \ldots, K_{n-1}) \right\|_p  \leq A_p B_p \prod_{i=1}^{n-1} \|K_i\|_p.
\end{align}

\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi)\right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_j}(\phi_1)\right] (K_1, \ldots, K_{j-1}) \left[ \Gamma^{A_j, \ldots, A_n}(\phi_2)\right] (K_j, \ldots, K_{n-1}).
\end{split}

Assume first that $p=2$. In the case when $\phi_1$ and $\phi_2$ are elementary tensors, it is straightforward to check the identity \eqref{simplificationsepid}. In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_j})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_j})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \cdots \times \lambda_{A_n})$. For any $s \in S$ and any $t\in T$, we have
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \phi_{2,t} \right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_j}(\phi_{1,s})\right] (K_1, \ldots, K_{j-1}) \left[ \Gamma^{A_j, \ldots, A_n}(\phi_{2,t})\right] (K_j, \ldots, K_{n-1}).
\end{split}
\end{align}
For a fixed $s\in S$, $(\phi_{1,s} \phi_{2,t})_{t\in T}$ converges to $\phi_{1,s} \phi_2$ and $(\phi_{1,s} \phi_2)_{s\in S}$ converges to $\phi = \phi_1 \phi_2$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. Hence by taking the limit on $t\in T$ and then on $s\in S$ in \eqref{simplificationsepid2}, we get \eqref{simplificationsepid}.

Now let $1 \leq p <\infty$ and $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. Then equality \eqref{simplificationsepid} holds and by assumption, there exist $A_p, B_p >0$ such that
\begin{align*}
\begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi)\right] (K_1, \ldots, K_{n-1})\|_p \\
& \leq \| \left[ \Gamma^{A_1, \ldots, A_j}(\phi_1)\right] (K_1, \ldots, K_{j-1}) \|_p \| \left[ \Gamma^{A_j, \ldots, A_n}(\phi_2)\right] (K_j, \ldots, K_{n-1}) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p ~ B_p \|K_j \|_p \ldots \|K_{n+1}\|_p,
\end{split}
\end{align*}
which shows that $\Gamma^{A_1, \ldots, A_n}(\phi) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$. Finally, we deduce \eqref{simplificationsepid} by approximation like in the proof of Lemma $\ref{simplification1}$.

\begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \phi_{2,t} \right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_j}(\phi_{1,s})\right] (K_1, \ldots, K_{j-1}) \left[ \Gamma^{A_j, \ldots, A_n}(\phi_{2,t})\right] (K_j, \ldots, K_{n-1}).
\end{split}

Assume first that $p=2$. In the case when $\phi_1$ and $\phi_2$ are elementary tensors, it is straightforward to check the identity \eqref{simplificationsepid}. In the general case, we let $(\phi_{1,s})_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_j})$ and $(\phi_{2,t})_{t\in T} \subset L^{\infty}(\lambda_{A_j}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ be two nets converging to $\phi_1$ and $\phi_2$, respectively for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_j})$ and for the $w^*$-topology of $L^{\infty}(\lambda_{A_j} \times \cdots \times \lambda_{A_n})$. For any $s \in S$ and any $t\in T$, we have
\begin{align} \begin{split}
& \left[ \Gamma^{A_1, \ldots, A_n}(\phi_{1,s} \phi_{2,t} \right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_j}(\phi_{1,s})\right] (K_1, \ldots, K_{j-1}) \left[ \Gamma^{A_j, \ldots, A_n}(\phi_{2,t})\right] (K_j, \ldots, K_{n-1}).
\end{split}
\end{align}

Now let $1 \leq p <\infty$ and $K_1, \ldots, K_{n-1} \in \mathcal{S}^2(\mathcal{H}) \cap \mathcal{S}^p(\mathcal{H})$. Then equality \eqref{simplificationsepid} holds and by assumption, there exist $A_p, B_p >0$ such that
\begin{align*}
\begin{split}
& \| \left[ \Gamma^{A_1, \ldots, A_n}(\phi)\right] (K_1, \ldots, K_{n-1})\|_p \\
& \leq \| \left[ \Gamma^{A_1, \ldots, A_j}(\phi_1)\right] (K_1, \ldots, K_{j-1}) \|_p \| \left[ \Gamma^{A_j, \ldots, A_n}(\phi_2)\right] (K_j, \ldots, K_{n-1}) \|_p \\
& \leq A_p \|K_1\|_p \ldots \|K_{j-1}\|_p ~ B_p \|K_j \|_p \ldots \|K_{n+1}\|_p,
\end{split}
\end{align*}
which shows that $\Gamma^{A_1, \ldots, A_n}(\phi) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))$.

Let $1 \leq p < \infty$. Let $n \geq 2$ and $1\leq j \leq n$. Let $A_1, \ldots, A_n$ be selfadjoint operators in $\mathcal{H}$. Let $\phi \in L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_{j-1}} \times \lambda_{A_{j+1}} \times \cdots \times \lambda_{A_n})$ and assume, if $n\geq 3$, that
$$
\Gamma^{A_1, \ldots, A_{j-1}, A_{j+1}, \ldots, A_n}(\phi) \in \mathcal{B}_{n-2}(\mathcal{S}^p(\mathcal{H})).
$$
We define $\widetilde{\phi} \in L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$ by
\begin{equation} \widetilde{\phi}(x_1, \ldots, x_n) = \phi(x_1, \ldots, x_{j-1}, x_{j+1}, \ldots, x_n)
\end{equation}
a.e. on $\sigma(A_1) \times \cdots \times \sigma(A_n)$. Then
$$
\Gamma^{A_1, \ldots, A_n}(\widetilde{\phi}) \in \mathcal{B}_{n-1}(\mathcal{S}^p(\mathcal{H}))
$$
and for any $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$, we have
\begin{enumerate}
\item[(i)] If $2\leq j \leq n-1$,
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) \\
& \ \ \ \ \ \ \ \ \ = \left[ \Gamma^{A_1, \ldots, A_{j-1}, A_{j+1}, \ldots, A_n}(\phi)\right] \left(K_1, \ldots, K_{j-2}, K_{j-1}K_j, K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
\item[(ii)] If $j=1$,
\begin{align*}
\left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) = K_1\left[ \Gamma^{A_2, \ldots, A_n}(\phi)\right] \left(K_2, \ldots, K_{n-1}\right).
\end{align*}
\item[(iii)] If $j=n$,
\begin{align*}
\left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) = \left[ \Gamma^{A_1, \ldots, A_{n-1}}(\phi)\right] \left(K_1, \ldots, K_{n-2}\right) K_{n-1}.
\end{align*}
\end{enumerate}

We only prove $(i)$, in the case when $n\geq 3$. The case $n=2$ and the second and third claims can be proved similarly. Assume that $2\leq j \leq n-1$. We first assume that $p=2$. If $\phi = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_{j+1} \otimes \cdots \otimes f_n, f_i \in L^{\infty}(\lambda_{A_i}), 1\leq i\neq j \leq n$, we have
\begin{equation*}
\widetilde{\phi} = f_1 \otimes \cdots \otimes f_{j-1} \otimes 1 \otimes f_{j+1} \otimes \cdots \otimes f_n
\end{equation*}
so that
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) \\
&  = f_1(A_1)K_1 \ldots K_{j-2}f_{j-1}(A_{j-1}) K_{j-1} K_j f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_{j-1}, A_{j+1}, \ldots, A_n}(\phi)\right] \left(K_1, \ldots, K_{j-1}, K_j K_{j+1}, K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
By linearity, this formula holds true whenever $\phi \in L^{\infty}(\lambda_{A_1}) \otimes \cdots L^{\infty}(\lambda_{A_{j-1}}) \otimes L^{\infty}(\lambda_{A_{j+1}}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$.

In the general case, we let $(\phi_s)_{s\in S} \subset L^{\infty}(\lambda_{A_1}) \otimes \cdots L^{\infty}(\lambda_{A_{j-1}}) \otimes L^{\infty}(\lambda_{A_{j+1}}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$ to be a net converging to $\phi$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_{j-1}} \times \lambda_{A_{j+1}} \times \cdots \times \lambda_{A_n})$. For any $s\in S$, we define $\widetilde{\phi_s}$ as in \eqref{fortilde2}. Then, it is easy to see that $(\widetilde{\phi_s})_{s\in S}$ converges to $\widetilde{\phi}$ for the $w^*$-topology of $L^{\infty}(\lambda_{A_1} \times \cdots \times \lambda_{A_n})$. We conclude using the $w^*$-continuity of multiple operator integral like in the proof of Lemma $\ref{simplification1}$.

In the case when $1\leq p < \infty$, we argue as in the end of the proof of Lemma $\ref{simplification1}$. Details are left to the reader.

We only prove $(i)$, in the case when $n\geq 3$. The case $n=2$ and the second and third claims can be proved similarly. Assume that $2\leq j \leq n-1$. We first assume that $p=2$. If $\phi = f_1 \otimes \cdots \otimes f_{j-1} \otimes f_{j+1} \otimes \cdots \otimes f_n, f_i \in L^{\infty}(\lambda_{A_i}), 1\leq i\neq j \leq n$, we have
\begin{equation*}
\widetilde{\phi} = f_1 \otimes \cdots \otimes f_{j-1} \otimes 1 \otimes f_{j+1} \otimes \cdots \otimes f_n
\end{equation*}
so that
\begin{align*}
& \left[ \Gamma^{A_1, \ldots, A_n}(\widetilde{\phi})\right] (K_1, \ldots, K_{n-1}) \\
&  = f_1(A_1)K_1 \ldots K_{j-2}f_{j-1}(A_{j-1}) K_{j-1} K_j f_{j+1}(A_{j+1}) K_{j+1} \ldots K_{n-1}f_n(A_n) \\
& = \left[ \Gamma^{A_1, \ldots, A_{j-1}, A_{j+1}, \ldots, A_n}(\phi)\right] \left(K_1, \ldots, K_{j-1}, K_j K_{j+1}, K_{j+1}, \ldots, K_{n-1}\right).
\end{align*}
By linearity, this formula holds true whenever $\phi \in L^{\infty}(\lambda_{A_1}) \otimes \cdots L^{\infty}(\lambda_{A_{j-1}}) \otimes L^{\infty}(\lambda_{A_{j+1}}) \otimes \cdots \otimes L^{\infty}(\lambda_{A_n})$.

Therefore, for all $1 \leq i \leq n$ and for all $x_0, \ldots, x_n \in \mathbb{R}$,
\begin{align*}
&f^{[n]} (x_0,x_1,\ldots,x_n) \\
& \ \ \ \ = \dfrac{f^{[n-1]}(x_0,\ldots,x_{i-1}, x_{i+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{i-2}. x_{i},x_{i+1},\ldots,x_n)}{x_{i-1}-x_i}
\end{align*}
 if $x_{i-1} \neq x_i$ and
$$
f^{[n]} (x_0,x_1,\ldots,x_n) = \partial_i f^{[n-1]}(x_1,\ldots,x_n)
$$
if $x_{i-1}=x_i.$

Let $1 < p < \infty$, $n \in \mathbb{N}, n \geq 2$. Let $A_1, \ldots, A_{n-1}, A, B$ be selfadjoint operators in $\mathcal{H}$ such that $B-A \in \mathcal{S}^p(\mathcal{H})$. Let $f$ be $n$-times differentiable on $\mathbb{R}$ such that $f^{(n-1)}$ and $f^{(n)}$ are bounded. Then, for any $K_1, \ldots, K_{n-1} \in \mathcal{S}^p(\mathcal{H})$ and any $1 \leq j \leq n$ we have
\begin{align*}
& \left[ \Gamma^{A_1, \ldots A_{j-1}, B, A_j, \ldots, A_{n-1}}(f^{[n-1]}) - \Gamma^{A_1, \ldots A_{j-1}, A, A_j, \ldots, A_{n-1}}(f^{[n-1]})\right] (K_1, \ldots, K_{n-1}) \\
& \ = \left[ \Gamma^{A_1, \ldots, A_{j-1}, B, A, A_j, \ldots, A_{n-1}}(f^{[n]})\right](K_1, \ldots, K_{j-1}, B-A, K_j, \ldots K_{n-1}).
\end{align*}

\begin{split}
& f^{[n]}(x_0, \ldots, x_n).(x_{j-1} - x_j) \\
& \ \ \ = f^{[n-1]}(x_0,\ldots,x_{j-1}, x_{j+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{j-2}, x_{j},x_{j+1},\ldots,x_n).
\end{split}

\begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)Xp_k(A) - p_k(B)Xp_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)Xp_k(A) K_j, K_{j+1} \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)Xp_k(A) K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}

\begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)P_ip_k(A) - p_k(B)P_ip_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)P_ip_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)P_ip_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}

\begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, p_k(B)(B-A)p_k(A), K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)p_k(A) K_j, K_{j+1}, \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)p_k(A)K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}

Let $1 \leq j \leq n$. First note that we have the following equality: for any $(x_0, \ldots, x_n) \in \mathbb{R}^{n+1}$,
\begin{align} \begin{split}
& f^{[n]}(x_0, \ldots, x_n).(x_{j-1} - x_j) \\
& \ \ \ = f^{[n-1]}(x_0,\ldots,x_{j-1}, x_{j+1}, \ldots,x_n) - f^{[n-1]}(x_0,\ldots,x_{j-2}, x_{j},x_{j+1},\ldots,x_n).
\end{split}
\end{align}

Applying the operator $\left[\Gamma_{B,A}(\cdot)\right](K_1, \ldots, K_{j-1}, X, K_j, \ldots K_{n-1})$ to \eqref{eqfunc} gives, by Lemma $\ref{simplification1}$ and Lemma $\ref{simplification2}$,
\begin{align} \begin{split}
& \left[ \Gamma_{B,A}(f^{[n]})\right](K_1, \ldots, K_{j-1}, Bp_k(B)Xp_k(A) - p_k(B)Xp_k(A)A, K_j, \ldots, K_{n-1}) \\
& = \left[ \Gamma_B(f^{[n-1]})\right](K_1, \ldots, K_{j-1}, p_k(B)Xp_k(A) K_j, K_{j+1} \ldots, K_{n-1})\\
& \ \ \ \ - \left[ \Gamma_A(f^{[n-1]})\right](K_1, \ldots, K_{j-2}, p_k(B)Xp_k(A) K_{j-1}, K_j \ldots, K_{n-1}).
\end{split}
